def protocol():
    cards=''.join(f'''<button class="choice" data-choice="{k}" aria-pressed="false" type="button"><span class="choice-top"><span>ВАРИАНТ / 0{i+1}</span><span class="choice-check"></span></span><div class="choice-art">{svg_art(k)}</div><div><h2>{title}</h2><p>{copy}</p></div></button>''' for i,(k,title,copy) in enumerate([('face','Лицо','Возможность узнать себя в другом.'),('voice','Голос','То, как вы произносили чьё-то имя.'),('name','Имя','След, который останется после вас.')]))
    return f'''<section class="page-shell protocol-shell">{eyebrow('05','ПРОТОКОЛ ПРОДОЛЖЕНИЯ','ВАШ ВЫБОР МЕНЯЕТ ФИНАЛ')}<div class="protocol-header"><span class="micro muted">ПАМЯТЬ ОГРАНИЧЕНА. ВЫБОР — ВАШ.</span><div class="step-track"><span data-step-label>01 / 03</span><i class="active"></i><i></i><i></i></div></div><h1 class="protocol-title reveal" data-protocol-title>Что вы сохраните?</h1><p class="protocol-lead" data-protocol-lead>Система не может перенести всё. Когда останется место только для одного следа, какой станет вашим продолжением?</p><div class="choice-grid">{cards}</div><div class="protocol-bottom"><div><button class="protocol-back" data-protocol-back type="button" hidden>← ПРЕДЫДУЩИЙ ВОПРОС</button><p class="protocol-feedback" aria-live="polite">Выберите один след, чтобы продолжить.</p></div><button class="button" data-protocol-next disabled type="button">ПОДТВЕРДИТЬ ВЫБОР <span class="arrow">→</span></button></div><p class="protocol-footnote">В ЭТОМ АРХИВЕ НЕТ ПРАВИЛЬНЫХ ОТВЕТОВ. ЕСТЬ ТОЛЬКО ТО, ЧТО ВЫ ГОТОВЫ ОСТАВИТЬ.</p></section>'''

